```javascript
function gerarHistograma(img, titulo) {
  var validos = img.reduceRegion({
    reducer: ee.Reducer.countPixelsValid(),
    geometry: geometry,
    scale: 30,
    maxPixels: 1e10
  });

  print('Contagem de pixels válidos:', validos.get('count_pixels_valid'));

  if (validos.get('count_pixels_valid') < 100) {
    print(titulo + ': sem dados suficientes para gráfico');
    return null;
  }

  return ui.Chart.image.histogram(img, geometry, 30, null, null, null, 1e13)
    .setOptions({ title: titulo });
}

